n, m, q = map(int, input().split())
# 地图。mp是二维数组,使用二维数组表示地图。mp[i][j]表示地图第i+1行第j+1列的格点
mp = [[0 for _ in range(m)] for _ in range(n)]
# 将地图上x行y列的地方放上地雷
for _ in range(q):
    x, y = map(int, input().split())
    mp[x - 1][y - 1] = '*'
# 遍历整张地图,先从行开始
for i in range(n):
    # 然后是列
    for j in range(m):
        # 如果这里是地雷,那就不管了,只考虑不是地雷的地方
        if mp[i][j] == '*':
            continue
        # 对于不是地雷的格点,判断周边是否有地雷
        # 遍历周边的8个格子,也就是i+di, j+dj
        for di in [-1, 0, 1]:
            for dj in [-1, 0, 1]:
                # 判断这个格子是否存在
                if i + di < 0 or i + di >= n or j + dj < 0 or j + dj >= m:
                    continue
                if mp[i+di][j+dj] == '*':
                    mp[i][j] += 1
# 最后把答案输出即可完成本题
for i in range(n):
    print(' '.join(map(str, mp[i])))
